"""Generate the C byte resource for the polyglot launcher template."""

import argparse
from pathlib import Path
import sys


def render(data):
    lines = [
        "/* Generated by tools/embed_launcher.py; edit templates/launcher.sh.ps1. */",
        "#ifndef ANYBUNDLE_LAUNCHER_TEMPLATE_H",
        "#define ANYBUNDLE_LAUNCHER_TEMPLATE_H",
        "",
        "static const unsigned char launcher_template[] = {",
    ]
    for start in range(0, len(data), 16):
        lines.append("    " + ", ".join(f"0x{value:02x}" for value in data[start:start + 16]) + ",")
    lines.extend(["};", "", "#endif", ""])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the generated header is stale")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    template = root / "templates" / "launcher.sh.ps1"
    header = root / "src" / "launcher_template.h"
    # Universal newlines keep generated launchers identical after a CRLF checkout.
    data = template.read_text(encoding="utf-8").encode("utf-8")
    if not data.startswith(b"#!/usr/bin/env sh\n") or not data.endswith(b"\n") or b"\0" in data:
        parser.error("launcher template must start with the sh shebang, end in a newline, and contain no NUL bytes")
    generated = render(data)
    existing = header.read_text(encoding="ascii") if header.exists() else None
    if args.check:
        if existing != generated:
            print("Launcher resource is stale; run python tools/embed_launcher.py", file=sys.stderr)
            return 1
    elif existing != generated:
        with header.open("w", encoding="ascii", newline="\n") as stream:
            stream.write(generated)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
